using System.Windows.Media.Media3D;using ToneCustoms.ShellStudio.Core;
namespace ToneCustoms.ShellStudio.Geometry;
public sealed class WallMeshBuilder { public MeshGeometry3D Build(SceneObject wall,IEnumerable<WallOpening> openings){if(wall.Type!=SceneObjectType.Wall)throw new ArgumentException("Wall mesh requires a wall object.");var length=Math.Max(.05f,wall.Scale.X);var depth=Math.Max(.05f,wall.Scale.Y);var height=Math.Max(.05f,wall.Scale.Z);var cuts=openings.Select(x=>new Cut(Math.Clamp(x.Offset,0,length),Math.Clamp(x.Width,.05f,length),Math.Clamp(x.SillHeight,0,height),Math.Clamp(x.Height,.05f,height))).OrderBy(x=>x.Left).ToList();var mesh=new MeshGeometry3D();var cursor=-length/2;foreach(var cut in cuts){var left=Math.Max(-length/2,cut.Left-length/2);var right=Math.Min(length/2,cut.Right-length/2);if(right<=left)continue;if(left>cursor)AddBox(mesh,cursor,left,-depth/2,depth/2,0,height);var bottom=Math.Clamp(cut.Bottom,0,height);var top=Math.Clamp(cut.Top,0,height);if(bottom>0)AddBox(mesh,left,right,-depth/2,depth/2,0,bottom);if(top<height)AddBox(mesh,left,right,-depth/2,depth/2,top,height);cursor=Math.Max(cursor,right);}if(cursor<length/2)AddBox(mesh,cursor,length/2,-depth/2,depth/2,0,height);return mesh;}static void AddBox(MeshGeometry3D mesh,double x0,double x1,double y0,double y1,double z0,double z1){if(x1<=x0||y1<=y0||z1<=z0)return;var b=mesh.Positions.Count;mesh.Positions.Add(new(x0,y0,z0));mesh.Positions.Add(new(x1,y0,z0));mesh.Positions.Add(new(x1,y1,z0));mesh.Positions.Add(new(x0,y1,z0));mesh.Positions.Add(new(x0,y0,z1));mesh.Positions.Add(new(x1,y0,z1));mesh.Positions.Add(new(x1,y1,z1));mesh.Positions.Add(new(x0,y1,z1));int[] i={0,2,1,0,3,2,4,5,6,4,6,7,0,1,5,0,5,4,1,2,6,1,6,5,2,3,7,2,7,6,3,0,4,3,4,7};foreach(var n in i)mesh.TriangleIndices.Add(b+n);}readonly record struct Cut(float OffsetFromLeft,float Width,float Bottom,float Height){public float Left=>OffsetFromLeft-Width/2;public float Right=>OffsetFromLeft+Width/2;public float Top=>Bottom+Height;}}
